[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-cardiology",
  "answer": "노작성 호흡곤란+기좌호흡+양측 발목 부종은 심부전(특히 좌심부전+우심부전 동반)을 강하게 시사한다. 심부전 감별의 1차 검사는 ECG·흉부X선·BNP/NT-proBNP·심초음파이며, 신기능 저하 시사 소견이 있으므로 조영제·NSAID 관련 신손상과 약물 유지/중단을 함께 판단해야 한다. 이부프로펜과 메트포르민의 중단 여부는 '신기능 수치(eGFR/크레아티닌)와 체액 상태'를 확인한 뒤 결정해야 하며, 원격 텍스트만으로 중단/유지를 단정하지 않는다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "CV6", "evidence": "안정 시/눕기 힘든 호흡곤란(기좌호흡), 양측 발목 부종", "basis": "history" }
    ]
  },
  "hypotheses": [
    { "name": "급성 대상부전 심부전(좌심부전+우심부전, 박출률 미상)", "icd10": "I50.9", "must_not_miss": true, "probability_band": "high",
      "supports": [
        { "text": "2개월 진행성 노작성 호흡곤란", "basis": "history" },
        { "text": "기좌호흡(베개 2개)", "basis": "history" },
        { "text": "양측 발목 부종", "basis": "history" },
        { "text": "고혈압·당뇨 = 심부전 주요 위험 인자", "basis": "history" },
