      "supports": [
        { "text": "신기능 저하 시사(질문에 명시)", "basis": "history" },
        { "text": "메트포르민 복용 = 당뇨병성 신병증 가능성", "basis": "history" },
        { "text": "NSAID 복용 = 신혈류 감소", "basis": "history" }
      ],
      "against": [
        { "text": "기좌호흡은 심장성 폐울혈을 더 시사", "basis": "history" }
      ]
    },
    { "name": "NSAID/메트포르민 관련 체액 저류·대사성 산증", "icd10": "Y45.4 / E87.2", "must_not_miss": false, "probability_band": "medium",
      "supports": [
        { "text": "이부프로펜 복용 + 신기능 저하 시사", "basis": "history" },
        { "text": "메트포르민 + 신기능 저하 = 유산산증 위험", "basis": "guideline" }
      ],
      "against": [
        { "text": "2개월에 걸친 진행성 경과는 단순 약물 부작용만으로 설명하기 어려움", "basis": "history" }
